* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  background: #111;
  color: #eee;
  font-family: sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
}

#wrap {
  position: relative;
  width: 500px;
}

#score {
  margin-bottom: 6px;
  font-size: 18px;
}

#board {
  display: block;
  background: #000;
  border: 1px solid #444;
}

#gameover {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.75);
  color: #fff;
  text-align: center;
}

#gameover.hidden {
  display: none;
}

.go-text {
  font-size: 28px;
  margin-bottom: 10px;
}

.go-score {
  font-size: 18px;
  margin-bottom: 18px;
}

#playagain {
  font-size: 16px;
  padding: 8px 16px;
  cursor: pointer;
}

// Snake — minimal playable version (ticket 1)
// Game logic is separated from rendering.

const BOARD_SIZE = 20;       // fixed cells per row/column
const TICK_MS = 150;         // movement interval
const CANVAS_PX = 500;       // canvas pixel size

const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const scoreEl = document.getElementById('score');
const gameoverEl = document.getElementById('gameover');
const goScoreEl = gameoverEl.querySelector('.go-score');
const playAgainBtn = document.getElementById('playagain');

const CELL = CANVAS_PX / BOARD_SIZE;

// ---- Game state -----------------------------------------------------------
let snake, dir, nextDir, food, score, running, lastTick;

function resetGame() {
  const center = Math.floor(BOARD_SIZE / 2);
  // Snake starts at center, length 3, heading right.
  snake = [
    { x: center, y: center },
    { x: center - 1, y: center },
    { x: center - 2, y: center },
  ];
  dir = { x: 1, y: 0 };
  nextDir = { x: 1, y: 0 };
  score = 0;
  running = true;
  lastTick = 0;
  placeFood();
  updateScore();
  gameoverEl.classList.add('hidden');
}

function placeFood() {
  const occupied = new Set(snake.map(s => s.x + ',' + s.y));
  const empties = [];
  for (let y = 0; y < BOARD_SIZE; y++) {
    for (let x = 0; x < BOARD_SIZE; x++) {
      if (!occupied.has(x + ',' + y)) empties.push({ x, y });
    }
  }
  food = empties[Math.floor(Math.random() * empties.length)];
}

function updateScore() {
  scoreEl.textContent = 'Score: ' + score;
}

// ---- Game step (pure logic, one tick) -------------------------------------
function step() {
  dir = nextDir;

  const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

  // Wall collision.
  if (head.x < 0 || head.y < 0 || head.x >= BOARD_SIZE || head.y >= BOARD_SIZE) {
    return gameOver();
  }

  // Self collision (check against current body; tail will move unless growing).
  const growing = head.x === food.x && head.y === food.y;
  const bodyToCheck = growing ? snake : snake.slice(0, -1);
  if (bodyToCheck.some(s => s.x === head.x && s.y === head.y)) {
    return gameOver();
  }

  snake.unshift(head);

  if (growing) {
    score++;
    updateScore();
    placeFood();
  } else {
    snake.pop();
  }
}

function gameOver() {
  running = false;
  goScoreEl.textContent = 'Final score: ' + score;
  gameoverEl.classList.remove('hidden');
}

// ---- Rendering ------------------------------------------------------------
function render() {
  ctx.clearRect(0, 0, CANVAS_PX, CANVAS_PX);

  // Grid lines.
  ctx.strokeStyle = '#222';
  ctx.lineWidth = 1;
  for (let i = 1; i < BOARD_SIZE; i++) {
    ctx.beginPath();
    ctx.moveTo(i * CELL, 0);
    ctx.lineTo(i * CELL, CANVAS_PX);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * CELL);
    ctx.lineTo(CANVAS_PX, i * CELL);
    ctx.stroke();
  }

  // Food.
  ctx.fillStyle = '#e44';
  ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

  // Snake.
  ctx.fillStyle = '#4ade80';
  snake.forEach(s => {
    ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
  });
}

// ---- Loop -----------------------------------------------------------------
function loop(ts) {
  requestAnimationFrame(loop);
  if (!running) {
    render();
    return;
  }
  if (ts - lastTick >= TICK_MS) {
    lastTick = ts;
    step();
  }
  render();
}

// ---- Input ----------------------------------------------------------------
function setDirection(nx, ny) {
  // Prevent reversing into self.
  if (nx === -dir.x && ny === -dir.y) return;
  nextDir = { x: nx, y: ny };
}

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp':    case 'w': case 'W': setDirection(0, -1); break;
    case 'ArrowDown':  case 's': case 'S': setDirection(0, 1); break;
    case 'ArrowLeft':  case 'a': case 'A': setDirection(-1, 0); break;
    case 'ArrowRight': case 'd': case 'D': setDirection(1, 0); break;
    default: return;
  }
  e.preventDefault();
});

playAgainBtn.addEventListener('click', () => {
  resetGame();
});

// ---- Init -----------------------------------------------------------------
resetGame();
requestAnimationFrame(loop);

// Expose for debugging / testing.
window.__snake = { resetGame, step, render, state: () => ({ snake, dir, nextDir, food, score, running }) };

