* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  background: #111;
  color: #eee;
  font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

#wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px;
}

#score {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 1px;
  color: #eee;
}

#board-area {
  position: relative;
  width: 500px;
  height: 500px;
}

#board {
  display: block;
  background: #000;
  border: 1px solid #444;
  width: 500px;
  height: 500px;
}

/* Overlays cover the board area */
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.8);
  text-align: center;
}

.overlay.hidden {
  display: none;
}

/* Start menu */
#startmenu {
  flex-direction: column;
  gap: 18px;
}

.menu-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  background: rgba(20, 20, 20, 0.9);
  border: 1px solid #444;
  border-radius: 8px;
  padding: 28px 34px;
}

#title {
  font-size: 40px;
  font-weight: 800;
  letter-spacing: 8px;
  margin-bottom: 6px;
}

.row {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 16px;
}

.high-label {
  color: #aaa;
}

.high-value {
  font-weight: 700;
  color: #4ade80;
}

#boardsize {
  width: 90px;
  padding: 6px 8px;
  font-size: 16px;
  background: #000;
  color: #4ade80;
  border: 1px solid #444;
  border-radius: 4px;
  text-align: center;
}

button {
  font-size: 17px;
  font-weight: 600;
  padding: 10px 22px;
  cursor: pointer;
  background: #000;
  color: #4ade80;
  border: 1px solid #4ade80;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s, box-shadow 0.15s;
}

button:hover {
  background: #4ade80;
  color: #000;
  box-shadow: 0 0 12px #4ade80;
}

/* Ready overlay */
.ready-text {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #eee;
  animation: pulse 1.4s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

/* Game over */
#gameover {
  flex-direction: column;
  gap: 12px;
}

.go-text {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: 3px;
  color: #e44;
  margin-bottom: 8px;
}

.go-score {
  font-size: 20px;
  margin-bottom: 4px;
}

.go-high {
  font-size: 16px;
  color: #4ade80;
  margin-bottom: 8px;
}

/* Responsive: scale the board area to fit the viewport */
@media (max-width: 600px), (max-height: 600px) {
