  running = false;
  state = 'over';
  startMenu.classList.add('hidden');
  readyEl.classList.add('hidden');
  goScoreEl.textContent = 'Final score: ' + score;
  goHighEl.textContent = 'High score: ' + highScore;
  gameoverEl.classList.remove('hidden');
}

