function loop(ts) {
  requestAnimationFrame(loop);
  if (state !== 'playing') {
    // Keep the last frame drawn (menu/ready/game-over overlays sit on top).
    if (state === 'menu' || state === 'over') render(ts);
    return;
  }
  if (ts - lastTick >= TICK_MS) {
    lastTick = ts;
    step();
  }
  render(ts);
}

