* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --neon-cyan: #0ff;
  --neon-magenta: #f0f;
  --neon-lime: #39ff14;
  --neon-pink: #ff2fa0;
  --bg: #000;
}

html, body {
  height: 100%;
  background: radial-gradient(ellipse at center, #0a0a14 0%, #000 70%);
  color: #eee;
  font-family: "Segoe UI", "Orbitron", Roboto, Helvetica, Arial, sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

#wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 12px;
}

#score {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--neon-cyan);
  text-shadow: 0 0 6px var(--neon-cyan), 0 0 14px rgba(0, 255, 255, 0.6);
}

#board-area {
  position: relative;
  width: 500px;
  height: 500px;
}

#board {
  display: block;
  background: #000;
  border: 2px solid #0ff;
  border-radius: 6px;
  box-shadow: 0 0 12px var(--neon-cyan), 0 0 30px rgba(0, 255, 255, 0.45), inset 0 0 18px rgba(0, 255, 255, 0.15);
  width: 500px;
  height: 500px;
}

/* Overlays cover the board area */
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.75);
  text-align: center;
  backdrop-filter: blur(2px);
}

.overlay.hidden {
  display: none;
}

/* Start menu */
#startmenu {
  flex-direction: column;
  gap: 18px;
}

.menu-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  background: rgba(10, 10, 18, 0.92);
  border: 1px solid #0ff;
  border-radius: 10px;
  padding: 28px 34px;
  box-shadow: 0 0 14px var(--neon-cyan), 0 0 34px rgba(0, 255, 255, 0.35), inset 0 0 12px rgba(0, 255, 255, 0.12);
}

#title {
  font-size: 44px;
  font-weight: 800;
  letter-spacing: 10px;
  margin-bottom: 6px;
  color: var(--neon-magenta);
